public class EncryptionService {

    public static final String ALGORITHM = "PBKDF2WithHmacSHA1";
    public static final int KEY_LENGTH = 256;

    // demo salt for testing or first setup purpose
    public static final String DEFAULT_SALT = "WZeBXmCI9cAz3LyY9Sdllj9l5iPsXC";

    private static final Random RANDOM = new SecureRandom();
    private static final String ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    private static final int ITERATIONS = 10000;

    public static String generateSalt(int length) {
        StringBuilder saltStr = new StringBuilder(length);
        for (int i = 0; i < length; i++) {
            saltStr.append(ALPHABET.charAt(RANDOM.nextInt(ALPHABET.length())));
        }
        return new String(saltStr);
    }

    public static byte[] hash(char[] password, byte[] salt) {
        PBEKeySpec spec = new PBEKeySpec(password, salt, ITERATIONS, KEY_LENGTH);
        Arrays.fill(password, Character.MIN_VALUE);
        try {
            SecretKeyFactory skf = SecretKeyFactory.getInstance(ALGORITHM);
            return skf.generateSecret(spec).getEncoded();
        } catch (NoSuchAlgorithmException | InvalidKeySpecException e) {
            throw new AssertionError("Error while hashing a password: " + e.getMessage(), e);
        } finally {
            spec.clearPassword();
        }
    }

    public static String encrypt(String password, String salt) {
        if (Strings.isNullOrEmpty(salt)) {
            throw new InvalidConfigurationException("Invalid salt: Wrong configuration. Salt cannot be empty or null");
        }
        byte[] securePassword = hash(password.toCharArray(), salt.getBytes());
        return Base64.getEncoder().encodeToString(securePassword);
    }

    public static boolean isPasswordValid(String providedPassword,
                                          String securedPassword, String salt)
    {
        // Generate new secure password with the same salt
        String newSecurePassword = encrypt(providedPassword, salt);
        // Check if the passwords are equal
        return newSecurePassword.equalsIgnoreCase(securedPassword);
    }

}

@Service
@Slf4j
public class PermissionService {

    @Autowired
    private PermissionRepository permissionRepository;

    public Iterable<Permission> getPermissionList() {
        return permissionRepository.findAll();
    }

    public Permission getPermissionByKey(String key) {
        if (Strings.isNullOrEmpty(key)) {
            throw new InvalidPermissionDataException("Permission key cannot be null or empty");
        }
        Optional<Permission> userOpt = permissionRepository.findByPermission(key);
        if (userOpt.isPresent()) {
            return userOpt.get();
        }
        throw new PermissionNotFoundException(String.format("Permission not found for permission key = %s", key));
    }

    @Transactional
    public Permission createPermission(PermissionDTO permissionDTO) {
        if (permissionDTO == null) {
            throw new InvalidPermissionDataException("Permission data cannot be null or empty");
        }

        String permissionKey = permissionDTO.getPermission();

        if (Strings.isNullOrEmpty(permissionKey)) {
            throw new InvalidPermissionDataException("Permission key cannot be null or empty");
        }

        // check permission
        Optional<Permission> permissionOpt = permissionRepository.findByPermission(permissionKey);
        if (permissionOpt.isPresent()) {
            throw new PermissionNotFoundException(String.format("Permission %s already existing with the same key with Id = %s",
                    permissionKey, permissionOpt.get().getId()));
        }

        Permission permission = new Permission();
        permission.setPermission(permissionKey);

        permission.setNote(permissionDTO.getNote());
        permission.setEnabled(permissionDTO.isEnabled());

        Permission createdPermission = permissionRepository.save(permission);

        log.info(String.format("Created permission %s with Id = %s", permissionKey, createdPermission.getId()));
        return createdPermission;
    }

    @Transactional
    public Permission updatePermission(PermissionDTO permissionDTO) {
        if (permissionDTO == null) {
            throw new InvalidPermissionDataException("Permission data cannot be null");
        }

        Long permissionId = permissionDTO.getId();
        Optional<Permission> permissionOpt = permissionRepository.findById(permissionId);
        if (!permissionOpt.isPresent()) {
            throw new PermissionNotFoundException(String.format("The permission with the id = %s has not been found",
                    permissionId));
        }

        Permission permission = permissionOpt.get();
        String permissionKey = permissionDTO.getPermission();

        // check if exists a different configuration with the same permissionKey
        Optional<Permission> permissionByKeyOpt = permissionRepository.findByPermission(permissionKey);
        if (permissionByKeyOpt.isPresent()) {
            Permission permission1 = permissionByKeyOpt.get();
            if (!permission1.getId().equals(permission.getId())) {
                throw new InvalidPermissionDataException(String.format("Exists already a permission with the key %s." +
                        " Use another key", permissionKey));
            }
        }

        // update permission
        permission.setPermission(permissionDTO.getPermission());
        permission.setEnabled(permissionDTO.isEnabled());
        permission.setNote(permissionDTO.getNote());

        Permission updatedPermission = permissionRepository.save(permission);
        log.info(String.format("Permission with id = %s has been updated.", permission.getId()));

        return updatedPermission;
    }

    @Transactional
    public void deletePermissionByKey(String permissionKey) {
        if (Strings.isNullOrEmpty(permissionKey)) {
            throw new InvalidPermissionDataException("Permission key cannot be null or empty");
        }

        // check permission
        Optional<Permission> permissionOpt = permissionRepository.findByPermission(permissionKey);
        if (!permissionOpt.isPresent()) {
            throw new PermissionNotFoundException(String.format("Permission %s not found", permissionKey));
        }

        Permission permission = permissionOpt.get();

        // check usage
        Long rowsFound = permissionRepository.countPermissionUsage(permission.getId());
        if (rowsFound > 0) {
            // permission cannot be deleted
            throw new PermissionInUseException(String.format("The permission with key %s is in used (%s configuration rows)",
                    permissionKey, rowsFound));
        }

        permissionRepository.delete(permission);

        log.info(String.format("Deleted permission with key %s", permission.getPermission()));
    }

}

@Service
@Slf4j
public class RoleService {

    @Autowired
    private RoleRepository roleRepository;

    @Autowired
    private PermissionRepository permissionRepository;

    public Iterable<Role> getRoleList() {
        return roleRepository.findAll();
    }

    public Role getRoleById(Long id) {
        if (id == null) {
            throw new InvalidRoleIdentifierException("Id role cannot be null");
        }
        Optional<Role> roleOpt = roleRepository.findById(id);
        if (roleOpt.isPresent()) {
            return roleOpt.get();
        }
        throw new RoleNotFoundException(String.format("Role not found for Id = %s", id));
    }

    public static void validateRoleName(String roleName) {
        if (Strings.isNullOrEmpty(roleName)) {
            throw new InvalidRoleDataException(String.format("Invalid role name: %s", roleName));
        }
    }

    @Transactional
    public Role createRole(String roleStr) {
        validateRoleName(roleStr);

        // check roleStr not in use
        if (roleRepository.findByRole(roleStr).isPresent()) {
            String errMsg = String.format("The role %s already exists", roleStr);
            log.error(errMsg);
            throw new RoleInUseException(errMsg);
        }

        Role role = new Role();
        role.setRole(roleStr);

        role = roleRepository.save(role);
        log.info(String.format("Role %s %s has been created.", role.getId(), role.getRole()));

        return role;
    }

    @Transactional
    public void deleteRole(Long id) {
        Optional<Role> roleOpt = roleRepository.findById(id);
        if (!roleOpt.isPresent()) {
            String errMsg = String.format("Role not found for Id = %s cannot be deleted", id);
            log.error(errMsg);
            throw new RoleNotFoundException(errMsg);
        }

        Role role = roleOpt.get();

        // check if the role is in use
        Long countUsages = roleRepository.countRoleUsage(id);
        if (countUsages > 0) {
            String errMsg = String.format("The role %s %s is in use (%s users_roles configuration rows)" +
                            " and cannot be deleted", role.getId(), role.getRole(), countUsages);
            log.error(errMsg);
            throw new RoleInUseException(errMsg);
        }

        roleRepository.deleteById(id);
        log.info(String.format("Role %s has been deleted.", id));
    }

    // add or remove a permission on a role

    public static void validatePermissionKey(String permissionKey) {
        if (Strings.isNullOrEmpty(permissionKey)) {
            throw new InvalidPermissionDataException("Permission key cannot be null or empty");
        }
    }

    @Transactional
    public Role addPermissionOnRole(Long roleId, String permissionKey) {
        validatePermissionKey(permissionKey);

        // check role
        Optional<Role> roleOpt = roleRepository.findById(roleId);
        if (!roleOpt.isPresent()) {
            throw new RoleNotFoundException(String.format("Role not found with Id = %s", roleId));
        }
        Role role = roleOpt.get();

        // check if exists the permission key
        Permission permission;

        Optional<Permission> permissionOpt = permissionRepository.findByPermission(permissionKey);
        if (permissionOpt.isPresent()) {
            // the permission exists
            permission = permissionOpt.get();
        } else {
            // if the permission doesn't exists: create one
            permission = new Permission();
            permission.setPermission(permissionKey);

            permission = permissionRepository.save(permission);
        }

        // check if this role contains already the given permission
        if (role.getPermissions().contains(permission)) {
            throw new InvalidPermissionDataException(String.format("The permission %s has been already" +
                            " associated on the role %s", permission.getPermission(), role.getRole() ));
        }

        role.getPermissions().add(permission);
        roleRepository.save(role);

        log.info(String.format("Added permission %s on role id = %s", permissionKey, roleId));
        return roleRepository.findById(roleId).get();
    }

    @Transactional
    public Role removePermissionOnRole(Long roleId, String permissionKey) {
        validatePermissionKey(permissionKey);

        // check role
        Optional<Role> roleOpt = roleRepository.findById(roleId);
        if (!roleOpt.isPresent()) {
            throw new RoleNotFoundException(String.format("Role not found with Id = %s", roleId));
        }
        Role role = roleOpt.get();

        // check permission
        Optional<Permission> permissionOpt = permissionRepository.findByPermission(permissionKey);
        if (!permissionOpt.isPresent()) {
            throw new PermissionNotFoundException(String.format("Permission not found with Id = %s on role %s",
                    permissionKey, roleId));
        }

        Permission permission = permissionOpt.get();

        role.getPermissions().remove(permission);
        roleRepository.save(role);

        log.info(String.format("Removed permission %s from role id = %s", permissionKey, roleId));
        return roleRepository.findById(roleId).get();
    }

}

